/* nfkc.c - full NFKC normalization core (UAX #15).
 *
 * Pipeline per Unicode Normalization Form:
 *   1. NFKD decomposition (canonical + compatibility, fully pre-expanded).
 *   2. Canonical ordering: stable sort by canonical combining class.
 *   3. Recomposition with the UAX #15 blocking rule.
 *
 * Tables are generated by scripts/gen_nfkc_tables.py from Python's
 * unicodedata (Unicode standard) and #included below.
 */
#include "nfkc.h"

#include <stdlib.h>
#include <string.h>

#include "nfkc_tables.inc"

/* BMP fast path: direct index table cp -> decomp entry index.
 * Built lazily, freed never (small). */
static uint32_t *s_decomp_index = NULL; /* UINT32_MAX = none */

static void ensure_index(void) {
    if (s_decomp_index) return;
    uint32_t *idx = (uint32_t *)malloc(0x30000 * sizeof(uint32_t));
    if (!idx) return;
    memset(idx, 0xFF, 0x30000 * sizeof(uint32_t));
    for (uint32_t i = 0; i < NFKC_DECOMP_N; i++) {
        uint32_t cp = kNfkcDecompEntries[i].cp;
        if (cp < 0x30000) idx[cp] = i;
    }
    s_decomp_index = idx;
}

static const uint32_t kNoIdx = 0xFFFFFFFFu;

static uint32_t decomp_index(uint32_t cp) {
    if (!s_decomp_index) ensure_index();
    if (s_decomp_index && cp < 0x30000) return s_decomp_index[cp];
    /* fallback: binary search */
    uint32_t lo = 0, hi = NFKC_DECOMP_N;
    while (lo < hi) {
        uint32_t mid = (lo + hi) / 2;
        if (kNfkcDecompEntries[mid].cp < cp) lo = mid + 1;
        else hi = mid;
    }
    if (lo < NFKC_DECOMP_N && kNfkcDecompEntries[lo].cp == cp) return lo;
    return kNoIdx;
}

static uint32_t compose_lookup(uint32_t a, uint32_t b) {
    uint32_t lo = 0, hi = NFKC_COMPOSE_N;
    while (lo < hi) {
        uint32_t mid = (lo + hi) / 2;
        uint32_t ma = kNfkcComposeEntries[mid].a;
        uint32_t mb = kNfkcComposeEntries[mid].b;
        if (ma < a || (ma == a && mb < b)) lo = mid + 1;
        else hi = mid;
    }
    if (lo < NFKC_COMPOSE_N && kNfkcComposeEntries[lo].a == a &&
        kNfkcComposeEntries[lo].b == b)
        return kNfkcComposeEntries[lo].c;
    return 0;
}

static uint32_t ccc_lookup(uint32_t cp) {
    uint32_t lo = 0, hi = NFKC_CCC_N;
    while (lo < hi) {
        uint32_t mid = (lo + hi) / 2;
        if (kNfkcCccEntries[mid].cp < cp) lo = mid + 1;
        else hi = mid;
    }
    if (lo < NFKC_CCC_N && kNfkcCccEntries[lo].cp == cp)
        return kNfkcCccEntries[lo].ccc;
    return 0;
}

int nfkc_decompose_cp(uint32_t cp, const uint32_t **out_seq, size_t *out_len) {
    uint32_t idx = decomp_index(cp);
    if (idx == kNoIdx) return 0;
    const nfkc_decomp_entry *e = &kNfkcDecompEntries[idx];
    *out_seq = kNfkcDecompPool + e->off;
    *out_len = e->len;
    return 1;
}

int nfkc_ccc(uint32_t cp) { return (int)ccc_lookup(cp); }

uint32_t nfkc_compose(uint32_t a, uint32_t b) { return compose_lookup(a, b); }

void nfkc_normalize_cps(const uint32_t *cps, size_t n,
                        uint32_t **out, size_t *out_count) {
    *out = NULL;
    *out_count = 0;
    /* decompose */
    size_t cap = n * 2 + 64;
    uint32_t *buf = (uint32_t *)malloc(cap * sizeof(uint32_t));
    if (!buf) return;
    size_t m = 0;
    for (size_t i = 0; i < n; i++) {
        uint32_t idx = decomp_index(cps[i]);
        if (idx != kNoIdx) {
            const nfkc_decomp_entry *e = &kNfkcDecompEntries[idx];
            if (m + e->len > cap) {
                size_t ncap = cap * 2 + 64;
                uint32_t *nb = (uint32_t *)realloc(buf, ncap * sizeof(uint32_t));
                if (!nb) { free(buf); return; }
                buf = nb; cap = ncap;
            }
            memcpy(buf + m, kNfkcDecompPool + e->off, e->len * sizeof(uint32_t));
            m += e->len;
        } else {
            if (m + 1 > cap) {
                size_t ncap = cap * 2 + 64;
                uint32_t *nb = (uint32_t *)realloc(buf, ncap * sizeof(uint32_t));
                if (!nb) { free(buf); return; }
                buf = nb; cap = ncap;
            }
            buf[m++] = cps[i];
        }
    }
    /* canonical ordering: stable insertion sort by combining class */
    for (size_t i = 1; i < m; i++) {
        uint32_t cc = ccc_lookup(buf[i]);
        if (cc == 0) continue;
        size_t j = i;
        while (j > 0 && ccc_lookup(buf[j - 1]) > cc) j--;
        if (j < i) {
            uint32_t t = buf[i];
            memmove(buf + j + 1, buf + j, (i - j) * sizeof(uint32_t));
            buf[j] = t;
        }
    }
    /* recomposition (UAX #15: starter + c compose when not blocked) */
    {
        size_t w = 0;
        uint32_t starter = 0xFFFFFFFFu;
        uint32_t last_cc = 0;
        for (size_t i = 0; i < m; i++) {
            uint32_t c = buf[i];
            uint32_t cc = ccc_lookup(c);
            if (starter != 0xFFFFFFFFu && (last_cc < cc || last_cc == 0)) {
                uint32_t comp = compose_lookup(starter, c);
                if (comp) {
                    starter = comp;
                    last_cc = 0;
                    buf[w - 1] = comp;
                    continue;
                }
            }
            if (cc == 0) {
                starter = c;
                last_cc = 0;
            } else {
                last_cc = cc;
            }
            buf[w++] = c;
        }
        m = w;
    }
    *out = buf;
    *out_count = m;
}
